class Solution {
public:
    bool canVisitAllRooms(vector<vector<int>>& rooms) {
        vector<bool> seen(rooms.size(), false);
        queue<int> q;
        q.push(0);
        seen[0] = true;
        int count = 0;
        while (!q.empty()) {
            int room = q.front(); q.pop(); ++count;
            for (int next : rooms[room]) if (!seen[next]) {
                seen[next] = true;
                q.push(next);
            }
        }
        return count == (int)rooms.size();
    }
};
